  providedIn: 'root',
})
export class WebserveraddressService {

  constructor() {
  }

  public getURL(endpoint: Endpoints): string {
    //return WebserverUrls.TEST + endpoint;
    return WebserverUrls.TEST + endpoint;
  }

}

